SELECT p.*, u.user_name, u.user_avatar, t.name AS tag_name
FROM post p
LEFT JOIN `user` u ON u.id = p.user_id
LEFT JOIN post_tag t ON t.id = p.tag_id

    AND p.title LIKE CONCAT('%', #{title}, '%')
    AND p.tag_id = #{tagId}
    AND p.user_id = #{userId}
    AND p.status = #{status}
    AND p.is_top = #{isTop}

        AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))

    AND p.create_time BETWEEN #{startTime} AND #{endTime}


    ORDER BY p.hot_score DESC, p.create_time DESC
    ORDER BY p.is_top DESC, p.create_time DESC

LIMIT #{current}, #{size}

SELECT COUNT(*) FROM post p

    AND p.title LIKE CONCAT('%', #{title}, '%')
    AND p.tag_id = #{tagId}
    AND p.user_id = #{userId}
    AND p.status = #{status}
    AND p.is_top = #{isTop}

        AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))

    AND p.create_time BETWEEN #{startTime} AND #{endTime}

SELECT id, title, hot_score as hotScore, view_count as viewCount, like_count as likeCount
FROM post WHERE status = 1
ORDER BY hot_score DESC LIMIT #{limit}
